  let S := ![{i₀}, {i₁}, s];
  Set.univ.PairwiseDisjoint S →
    let φ := fun x =>
      match (motive := (x : J) → ({ x_1 // x_1 ∈ S x } → G) → G) x with
      | 0 => fun Ys => Ys ⟨i₀, ⋯⟩
      | 1 => fun Ys => Ys ⟨i₁, ⋯⟩
      | 2 => fun Ys => ∑ i : { x // x ∈ s }, Ys ⟨↑i, ⋯⟩;
    (∀ (j : J), Measurable (φ j)) → iIndepFun (fun x => hG) ![Y i₀, Y i₁, ∑ i ∈ s, Y i] μ := sorry

